def balanced_brackets(s: str) -> bool:
    """Return True if (), [], {} are properly nested and closed in s,
    ignoring all other Unicode code points."""
    pairs = {')': '(', ']': '[', '}': '{'}
    stack: list[str] = []
    for ch in s:
        if ch in '({[':
            stack.append(ch)
        elif ch in ')}]':
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack
